import { test, expect } from '@playwright/test';

test.describe('Out-of-stock message when adding unavailable item to cart', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://demo.playwright.dev/shop');
  });

  test('should display out-of-stock message for unavailable item', async ({ page }) => {
    // Find an out-of-stock product
    const outOfStockProduct = page.getByRole('button', { name: /out of stock/i }).first();

    // Verify the out-of-stock button is visible
    await expect(outOfStockProduct).toBeVisible();

    // Click the out-of-stock button
    await outOfStockProduct.click();

    // Verify that an error message or notification appears
    const errorMessage = page.getByText(/out of stock|unavailable|not available/i);
    await expect(errorMessage).toBeVisible();
  });

  test('should prevent adding out-of-stock item to cart', async ({ page }) => {
    // Find the add to cart button for an out-of-stock item
    const addToCartButtons = page.getByRole('button', { name: /add to cart/i });

    // Get the first product section
    const firstProduct = page.locator('[data-testid="product-item"]').first();

    // Check if product is marked as out of stock
    const stockStatus = firstProduct.getByText(/out of stock|unavailable/i);

    if (await stockStatus.isVisible()) {
      // Try to click add to cart for out-of-stock item
      const addButton = firstProduct.getByRole('button', { name: /add to cart/i });

      if (await addButton.isEnabled()) {
        await addButton.click();

        // Verify error message appears
        const errorNotification = page.getByRole('alert').or(page.getByText(/cannot add|out of stock|unavailable/i));
        await expect(errorNotification).toBeVisible();
      } else {
        // Button should be disabled for out-of-stock items
        await expect(addButton).toBeDisabled();
      }
    }
  });

  test('should show stock status message on product details', async ({ page }) => {
    // Navigate to a product page
    const productLink = page.getByRole('link').filter({ hasText: /product/i }).first();
    await productLink.click();

    // Wait for page to load
    await page.waitForLoadState('networkidle');

    // Check for stock status information
    const stockInfo = page.getByText(/in stock|out of stock|availability/i);
    await expect(stockInfo).toBeVisible();

    // If out of stock, verify the add to cart button is disabled or shows error
    const outOfStockText = page.getByText(/out of stock/i);
    if (await outOfStockText.isVisible()) {
      const addToCartButton = page.getByRole('button', { name: /add to cart/i });

      // Button should either be disabled or clicking it should show an error
      const isDisabled = await addToCartButton.isDisabled();
      expect(isDisabled).toBeTruthy();
    }
  });

  test('should display clear error message when attempting to add out-of-stock item', async ({ page }) => {
    // Find product container
    const products = page.locator('[data-testid="product-item"]');
    const productCount = await products.count();

    // Iterate through products to find out-of-stock item
    for (let i = 0; i < productCount; i++) {
      const product = products.nth(i);
      const outOfStockBadge = product.getByText(/out of stock|unavailable/i);

      if (await outOfStockBadge.isVisible()) {
        const addButton = product.getByRole('button', { name: /add to cart/i });

        // Attempt to add to cart
        if (await addButton.isEnabled()) {
          await addButton.click();

          // Verify error message
          const errorMsg = page.getByRole('alert').or(page.getByText(/out of stock|cannot add|item unavailable/i));
          await expect(errorMsg).toBeVisible();

          // Verify error message contains relevant information
          const errorText = await errorMsg.textContent();
          expect(errorText).toMatch(/out of stock|unavailable|cannot add/i);
        } else {
          // Verify button is disabled with appropriate styling
          await expect(addButton).toBeDisabled();
        }

        break;
      }
    }
  });
});
